 var ranges;
 let seed = Math.random() * 1241;
 var mySize;
 let str_wei = 0;
 let x_space;

 // colors
 let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let colors1 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
 let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselet = [];
 let plus1, plus2, margin;
 let tile_count = 10;
 let h_size;
 let plus_wei;
 let plus_dis

 function setup() {
 	// pixelDensity(5);
 	background("#202020");
 	frameRate(25);
 	randomSeed(seed);
 	mySize = max(windowWidth, windowHeight);
 	// createCanvas(mySize / 16 * 14, mySize / 16 * 14);
 	// createCanvas(mySize, mySize / 16 * 4);
 	createCanvas(windowWidth, windowHeight);
 	// createCanvas(1920/3*1.75, 1080/3*1.75);
 	background("#202020");
 	margin = mySize / 100;
 	ranges = 1 * random([10, 5, 25, 40]);
 	// ranges = 50;
 	color1 = random(colors1);
 	color2 = random(colors2);
 	plus1 = plus2 = 0;
 	h_size = int(random(100, 50));
 	x_space = int(random(4, 15));
 	plus_dis = 0.01;
 	plus_wei = plus_dis;
 	background("#202020");
 }

 function draw() {
 	background("#2020201a");
 	randomSeed(seed);
 	noiseSeed(seed);
 	colorselet[0] = random(colors2);
 	colorselet[1] = random(colors2);
 	colorselet[2] = random(colors2);
 	colorselet[3] = random(colors2);
 	colorselet[4] = random(colors2);
 	colorselet[5] = random(colors2);
 	PulseWave1();
 	PulseWave2();

 	//frame
 	drawingContext.shadowColor = random(colors1);
 	drawingContext.shadowOffsetX = 0;
 	drawingContext.shadowOffsetY = 0;
 	drawingContext.shadowBlur = 0;
 	// noFill();
 	// stroke("#202020");
 	// strokeWeight(margin);
 	// rect(0, 0, width, height);
 }

 // by SamuelYAN
 // more works //
 // https://twitter.com/SamuelAnn0924
 // https://www.instagram.com/samuel_yan_1990/

 function PulseWave1() {
 	noFill();
 	let res = random(0.01, 0.005);
 	for (let i = 0; i < ranges; i++) { // noprotect
 		strokeWeight(str_wei);
 		strokeCap(SQUARE);

 		stroke(random(colorselet));
 		if (ranges % 3 == 0) {
 			drawingContext.shadowColor = random(colorselet);
 			drawingContext.shadowOffsetX = 1;
 			drawingContext.shadowOffsetY = 1;
 			drawingContext.shadowBlur = 0;
 		} else {
 			drawingContext.shadowColor = random(colorselet);
 			drawingContext.shadowOffsetX = -1;
 			drawingContext.shadowOffsetY = -1;
 			drawingContext.shadowBlur = 0;
 		}
 		let size_xx = int(random(1, 0.1));
 		let size_yy = int(random(50, 100));
 		beginShape();
 		for (let x = -width * 0.5; x < width * 1.5; x += x_space) {
 			let n = noise(x * 0.005, i * 0.01, frameCount * res);
 			let y = map(n, 0, 1, -height * 0.5, height * 2);
 			line(x + size_xx * sin(plus1), y + size_yy * cos(plus1), x + size_xx * sin(plus1), y - size_yy * cos(plus1));
 		}
 		endShape();

 	}


 	if (plus_wei == plus_dis && str_wei < 1) {
 		str_wei += plus_dis;
 	}
 	if (plus_wei == plus_dis && str_wei >= 1) {
 		plus_wei = -plus_dis;
 	}
 	if (plus_wei == -plus_dis) {
 		str_wei += -plus_dis;
 	}
 	if (plus_wei == -plus_dis && str_wei <= 0.1) {
 		plus_wei = plus_dis;
 	}

 	plus1 += random(0.01, 0.01);

 }

 function PulseWave2() {
 	noFill();
 	let res = random(0.01, 0.005);
 	for (let i = 0; i < ranges; i++) { // noprotect
 		strokeWeight(str_wei);
 		strokeCap(SQUARE);

 		stroke(random(colorselet));
 		if (ranges % 3 == 0) {
 			drawingContext.shadowColor = random(colors0);
 			drawingContext.shadowOffsetX = 1;
 			drawingContext.shadowOffsetY = 1;
 			drawingContext.shadowBlur = 0;
 		} else {
 			drawingContext.shadowColor = random(colors1);
 			drawingContext.shadowOffsetX = -1;
 			drawingContext.shadowOffsetY = -1;
 			drawingContext.shadowBlur = 0;
 		}
 		let size_xx = int(random(1, 0.1));
 		let size_yy = int(random(100, 50));
 		for (let x = -width * 0.1; x < width * 1.5; x += x_space) {
 			let n = noise(x * 0.005, i * 0.01, frameCount * res);
 			let y = map(n, 0, 1, height * 2, -height * 0.5);
 			line(x - size_xx * cos(plus2), y - size_yy * sin(plus2), x - size_xx * cos(plus2), y + size_yy * sin(plus2));
 		}
 	}


 	if (plus_wei == plus_dis && str_wei < 1) {
 		str_wei += plus_dis;
 	}
 	if (plus_wei == plus_dis && str_wei >= 1) {
 		plus_wei = -plus_dis;
 	}
 	if (plus_wei == -plus_dis) {
 		str_wei += -plus_dis;
 	}
 	if (plus_wei == -plus_dis && str_wei <= 0.1) {
 		plus_wei = plus_dis;
 	}

 	plus2 += random(0.01, 0.05);

 }

